function safeUpdateErrorMessage(error) {
  const keys = {
    channel: 'updateChannelUnavailable',
    network: 'updateNetworkUnavailable',
    verification: 'updateVerificationFailed',
    storage: 'updateStorageFailed',
    unknown: 'updateUnknownError'
